const base = (includeLine) => `workspace "Test" "Test" {
    model {
        policyholder = person "Policyholder" "A policyholder"
        claimsCenter = softwareSystem "Claims Center" "A system" {
            webPortal = container "Web Portal" "A portal" "Web Application"
            mobileAppBackend = container "Mobile App Backend" "A backend" "API"
        }
        policyholder -> webPortal "uses"
    }
    views {
        container claimsCenter "test" "Test view" {
            ${includeLine}
            autoLayout
        }
    }
}`;

const tests = {
  "single": base("include policyholder"),
  "comma_space": base("include policyholder, webPortal"),
  "comma_nospace": base("include policyholder,webPortal"),
  "space_sep": base("include policyholder webPortal"),
  "star": base("include *"),
};

const out = {};
for (const [name, dsl] of Object.entries(tests)) {
  const r = await tools.structurizr.validate({ dsl });
  out[name] = r;
}
return out;

